import sys
from collections import defaultdict


def minutes(text):
    h, m = text.split(":")
    return int(h) * 60 + int(m)


def main():
    totals = defaultdict(int)

    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) != 3:
            continue
        name, start, end = parts

        start_min = minutes(start)
        end_min = minutes(end)

        if end_min < start_min:
            worked_min = (24 * 60 - start_min) + end_min
        elif end_min == start_min:
            worked_min = 0
        else:
            worked_min = end_min - start_min

        if worked_min > 6 * 60:
            if worked_min > 9 * 60:
                worked_min -= 45
            else:
                worked_min -= 30

        totals[name] += worked_min

    for name in sorted(totals.keys()):
        total_min = totals[name]
        h = total_min // 60
        m = total_min % 60
        print(f"{name} {h:02d}:{m:02d}")


if __name__ == "__main__":
    main()
